import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import AuthPages from './components/AuthPages'; // <--- IMPORT THE NEW FILE HERE
import DailyTracker from './components/DailyTracker'; // Your existing tracker
import { AuthProvider } from './context/AuthContext'; // Assuming you have this

function App() {
  return (
    <AuthProvider>
      <Router>
        <Routes>
          {/* Show the new professional Auth page for Login */}
          <Route path="/login" element={<AuthPages />} />
          
          {/* Show the new professional Auth page for Register */}
          <Route path="/register" element={<AuthPages />} />
          
          {/* Your main app */}
          <Route path="/tracker" element={<DailyTracker />} />
          
          {/* Redirect root to login */}
          <Route path="/" element={<Navigate to="/login" />} />
        </Routes>
      </Router>
    </AuthProvider>
  );
}

export default App;
